import UnderlineHeading from '@/components/heading/UnderlineHeading';
import DocumentUpload from '../components/addEmployee/DocumentUpload';
import AddEmployeeForm from '../forms/addEmployee/AddEmployeeForm';
import { Link } from 'react-router-dom';
import { SubtleButton } from '@/components/buttons/SubtleButton';

export default function AddEmployeePage() {
    return (
        <div className="w-full mt-6">
            <div className="flex flex-row justify-between mb-6">
                <UnderlineHeading className="h-fit" text="اضافة موظف جديد" />
                <div className="flex flex-row gap-2">

                    <DocumentUpload />
                    <Link to="/human-resources/employees">
                        <SubtleButton>العودة</SubtleButton>
                    </Link>
                </div>
            </div>
            <AddEmployeeForm />
        </div>
    );
}
